function registerChatRoutes(app2, getSessionUser2) {
  const requireAuth = (req, res, next) => {
    const db = readDb();
    const user = getSessionUser2(req, db);
    if (!user) {
      return res.status(401).json({ error: "Authentication required to access friend chat" });
    }
    req.sessionUser = user;
    next();
  };
  app2.post(
    "/api/chat/rooms",
    requireAuth,
    (req, res) => createChatRoom(req, res, req.sessionUser)
  );
  app2.post(
    "/api/chat/rooms/join",
    requireAuth,
    (req, res) => joinChatRoom(req, res, req.sessionUser)
  );
  app2.get(
    "/api/chat/rooms/my",
    requireAuth,
    (req, res) => getMyChatRooms(req, res, req.sessionUser)
  );
  app2.get(
    "/api/chat/rooms/:roomId",
    requireAuth,
    (req, res) => getChatRoomDetails(req, res, req.sessionUser)
  );
  app2.get(
    "/api/chat/rooms/:roomId/messages",
    requireAuth,
    (req, res) => getChatMessageHistory(req, res, req.sessionUser)
  );
  app2.post(
    "/api/chat/rooms/:roomId/messages",
    requireAuth,
    (req, res) => sendChatMessage(req, res, req.sessionUser)
  );
  app2.delete(
    "/api/chat/rooms/:roomId/messages/:messageId",
    requireAuth,
    (req, res) => deleteChatMessage(req, res, req.sessionUser)
  );
  app2.post(
    "/api/chat/rooms/:roomId/leave",
    requireAuth,
    (req, res) => leaveChatRoom(req, res, req.sessionUser)
  );
  app2.post(
    "/api/chat/rooms/:roomId/close",
    requireAuth,
    (req, res) => closeChatRoom(req, res, req.sessionUser)
  );
  app2.delete(
    "/api/chat/rooms/:roomId",
    requireAuth,
    (req, res) => deleteChatRoom(req, res, req.sessionUser)
  );
  app2.get(
    "/api/chat/rooms/:roomId/stream",
    requireAuth,
    (req, res) => handleChatSSEStream(req, res, req.sessionUser)
  );
  console.log("[Chat Service] Mounted all /api/chat/* endpoints successfully");
}

