function isNumericalSubject(subjectName, units = []) {
  const text = `${subjectName} ${units.map((u) => `${u.name} ${(u.topics || []).map((t) => t.name).join(" ")}`).join(" ")}`.toLowerCase();
  const numericalKeywords = [
    "math",
    "calculus",
    "algebra",
    "numerical",
    "physics",
    "circuit",
    "network",
    "mechanics",
    "thermodynamic",
    "statistics",
    "probability",
    "geometry",
    "matrix",
    "matrices",
    "differential",
    "integral",
    "fourier",
    "laplace",
    "accounting",
    "finance",
    "algorithm",
    "complexity",
    "digital",
    "signal",
    "logic design",
    "electronic",
    "fluid",
    "electrical",
    "chemistry",
    "kinematics"
  ];
  return numericalKeywords.some((kw) => text.includes(kw));
}
